process = controller._WorkloadProcess(("/usr/bin/true",), start_new_session=True) controller._workload_owners[process.pid] = process original_waitpid = os.waitpid receipt = {"reaped": False, "returncode": None} attempts = [] audit = {"pid": process.pid, "deadline": deadline, "outcome": outcome} tick = 99.999
def clock(): nonlocal tick tick += 0.001 return round(tick, 6)
def waitpid(pid, options): assert receipt["authority_closed_monotonic"] == 100.0 assert pid == process.pid and options == os.WNOHANG attempts.append((pid, options)) if outcome == "missing": raise ChildProcessError(errno.ECHILD, "simulated ownership loss") if outcome == "withheld": return 0, 0 return original_waitpid(pid, options)
def forbidden_sleep(seconds): raise AssertionError("expired reap must not sleep or renew polling")
try: assert controller._wait(process.pid, time.monotonic() + 2) audit["before"] = inspect_pid(process.pid) assert audit["before"]["state"] == "zombie" with monkeypatch.context() as patch: patch.setattr(controller.time, "monotonic", clock) patch.setattr(controller.time, "sleep", forbidden_sleep) patch.setattr(controller.os, "waitpid", waitpid) controller._reap_leader(process, deadline, receipt) audit.update(receipt=receipt, attempts=attempts) > assert attempts == [(process.pid, os.WNOHANG)] E assert [] == [(10429, 1)] E E Right contains one more item: (10429, 1) E E Full diff: (-: missing in left side, +: extra in left side) E + [] E - [ E - ( E - 10429, E - 1, E - ), E - ]
